import { readFile, writeFile } from "fs/promises";
import { join } from "path";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";
import { createForks, teardownForks } from "@tigrisdata/agent-kit";

async function main() {
  const projectDir = "/home/user/seeded-fork";
  const trialIdPath = "/logs/artifacts/trial_id";
  const forksJsonPath = join(projectDir, "forks.json");

  // 1. Read trial ID and construct normalized source bucket name
  const rawTrialId = await readFile(trialIdPath, "utf-8");
  const trialId = rawTrialId.trim();
  const sourceBucketName = `harbor-seeded-${trialId}`
    .toLowerCase()
    .replace(/[^a-z0-9.-]/g, "-");

  console.log(`Source bucket name: ${sourceBucketName}`);

  // 2. Upload local files to the source bucket using AWS SDK v3
  const s3Client = new S3Client({
    region: "REDACTED",
    endpoint: "REDACTED",
    credentials: {
      accessKeyId: process.env.TIGRIS_STORAGE_ACCESS_KEY_ID!,
      secretAccessKey: process.env.TIGRIS_STORAGE_SECRET_ACCESS_KEY!,
    },
  });

  const filesToUpload = ["a.txt", "b.txt", "c.txt"];
  for (const filename of filesToUpload) {
    const filePath = join(projectDir, "data", filename);
    const fileContent = await readFile(filePath);
    await s3Client.send(
      new PutObjectCommand({
        Bucket: sourceBucketName,
        Key: filename,
        Body: fileContent,
      })
    );
    console.log(`Uploaded ${filename} to ${sourceBucketName}`);
  }

  let forkSet;
  try {
    // 3. Create 2 forks
    const result = await createForks(sourceBucketName, 2, {
      prefix: "eval-dispatch",
      credentials: { role: "ReadOnly" },
    });

    if (result.error) {
      throw result.error;
    }

    forkSet = result.forkSet;
    if (!forkSet) {
        throw new Error("Failed to create forks: forkSet is undefined");
    }

    // 4. Write fork bucket names to forks.json
    const forkNames = forkSet.forks.map((f) => f.bucket);
    await writeFile(
      forksJsonPath,
      JSON.stringify({ forks: forkNames }, null, 2),
      "utf-8"
    );
    console.log(`Wrote fork names to ${forksJsonPath}`);

  } finally {
    // 5. Teardown forks
    if (forkSet) {
      await teardownForks(forkSet);
      console.log("Tore down forks");
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

